(function () {
  var all = window.DRAFT_PLAYERS || [];
  var nrm = function (s) { return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, ''); };
  var reg = { spike: 0.62, up: 0.85, stable: 1, down: 1, rookie: 1 };
  // Une poussee de production chez un jeune n'est pas un hasard : c'est une saison
  // d'eclosion. On garde une part croissante du gain quand l'age est dans la fenetre
  // de progression, et davantage encore si la hausse est reguliere d'annee en annee.
  var youth = function (age) {
    if (age == null) return 0.15;
    if (age <= 22) return 0.75;
    if (age === 23) return 0.65;
    if (age === 24) return 0.50;
    if (age === 25) return 0.35;
    if (age === 26) return 0.20;
    // 27 ans et plus : la fenetre d'eclosion est fermee. Avant, un joueur de 28 ans
    // (DeBrincat) heritait encore d'un bonus jeunesse et gardait trop de son pic.
    return 0;
  };
  // Progression reelle = chaque saison strictement au-dessus de la precedente.
  // Avec `<`, un profil plat-plat-pic (Schmaltz 1.61 / 1.61 / 2.07) passait pour
  // une progression et heritait du bonus +0.10 : c'est un pic, pas une montee.
  var rising = function (ss) {
    if (!ss || ss.length < 3) return false;
    for (var i = 1; i < ss.length; i++) if (ss[i].fpg <= ss[i - 1].fpg) return false;
    return true;
  };
  // Aucun des 27 gardiens n'a de saison dans VOLATILITY, et 15 d'entre eux heritent
  // du plancher 52 departs. Ce 52 ne veut pas dire « partant confirme a 52 matchs » :
  // il veut dire « aucune donnee de volume ». Leur rang n'etait donc qu'un taux non
  // verifie multiplie par un defaut — Wedgewood sortait 1er du tableau sur ce seul fait.
  var G_FLOOR = 52;
  var G_SHARE_LO = 0.62;  // part realiste d'un 1B dans un tandem (~32 departs)
  var G_HAIRCUT = 0.88;   // variance de taux, meme avec un volume connu

  // Dependance de role confirmee, saisie a la main : les projections ne contiennent
  // ni trios ni unites d'avantage numerique (voir AUDIT). Un role perdu et observe
  // n'est pas de la variance — on coupe. A etendre quand les unites sortent du camp.
  var ROLE_RISK = {
    rasmusandersson: { keep: 0.72, why: 'VGK roule 5 attaquants sur PP1 · 1B-4A en 12 matchs depuis l\'echange' }
  };

  all.forEach(function (p) {
    var v = window.VOLATILITY[nrm(p.name)];
    p.vol = v ? v.cls : null;
    p.volDelta = v ? v.delta : null;
    p.volSeasons = v ? v.seasons : null;
    p.volBase = v ? v.base : null;
    // Donnees minces : moins de 3 saisons de reference, la regression ne mord pas.
    p.dataThin = !v || !v.seasons || v.seasons.length < 3;
    // projection reregressee : on ramene une partie du pic vers la base
    if (v && (v.cls === 'spike' || v.cls === 'up') && v.cur > 0) {
      var k = reg[v.cls];
      var bonus = youth(p.age) + (rising(v.seasons) ? 0.10 : 0);
      var keep = Math.min(0.95, k + (1 - k) * bonus);
      p.regrKeep = Math.round(keep * 100) / 100;
      // le drapeau doit refleter l'age seul : « rising » a son propre drapeau
      p.regrYouth = youth(p.age) > 0;
      p.regrRising = rising(v.seasons);
      var tgt = v.base + (v.cur - v.base) * keep;
      p.proj_regr = Math.round(p.fp_proj * (tgt / v.cur));
      p.regrApplied = true;
    } else {
      // rien a regresser : la valeur reste comparable telle quelle
      p.proj_regr = p.fp_proj;
      p.regrApplied = false;
    }
    // Volume gardien : fourchette honnete au lieu d'un faux point.
    if (p.pos === 'G') {
      p.gpUnknown = p.gp_proj === G_FLOOR;
      var fpg = p.fpg_proj != null ? p.fpg_proj
        : (p.gp_proj ? p.fp_proj / p.gp_proj : 0);
      p.fp_hi = Math.round(fpg * p.gp_proj);
      p.fp_lo = Math.round(fpg * p.gp_proj * (p.gpUnknown ? G_SHARE_LO : G_HAIRCUT));
      if (p.gpUnknown) {
        // partage du filet aussi probable que non : on note le milieu de la fourchette
        p.proj_regr = Math.round((p.fp_hi + p.fp_lo) / 2);
        p.regrApplied = true;
        p.volNote = 'volume inconnu (plancher ' + G_FLOOR + ' departs) · fourchette '
          + p.fp_lo + '-' + p.fp_hi + ' FP';
      } else {
        p.proj_regr = p.fp_lo;
        p.regrApplied = true;
        p.volNote = p.gp_proj + ' departs projetes · donnee reelle';
      }
    }
    var rr = ROLE_RISK[nrm(p.name)];
    if (rr) {
      p.roleRisk = rr.why;
      p.proj_regr = Math.round(p.proj_regr * rr.keep);
      p.regrApplied = true;
    }
  });
  // VORP regresse : le remplacant se calcule lui aussi sur les projections
  // regressees, sinon on compare une valeur corrigee a une baseline brute.
  ['F','D','G'].forEach(function (pos) {
    var thr = { F: 73, D: 49, G: 17 }[pos];
    var at = all.filter(function (p) { return p.pos === pos; }).sort(function (a, b) { return b.proj_regr - a.proj_regr; });
    var rep = at[thr - 1] ? at[thr - 1].proj_regr : 0;
    at.forEach(function (p) { p.vorp_regr = p.proj_regr != null ? Math.round(p.proj_regr - rep) : null; });
  });
})();

/* ---------------------------------------------------------------------------
   PLANCHER GAGNE vs PROJECTION ACCORDEE

   Probleme de fond : fp_proj contient deja (a) le multiplicateur d'age et
   (b) un nombre de matchs accorde. La regression ne mordait que sur la part
   « pic », donc une projection pouvait depasser tout ce que le joueur a fait
   dans sa vie tout en s'affichant « aucune regression — rien a regresser ».
   Fantilli : 1.77 FP/PJ au mieux, projete a 1.93 → +9% jamais vu, drapeau zero.

   On calcule donc pour chaque joueur un plancher bati UNIQUEMENT sur du
   demontre : taux deja repete (jamais le pic isole), volume deja tenu, aucun
   bonus d'age. L'ecart entre plancher et projection est la part ACCORDEE par
   le modele, et elle est affichee avec ses raisons.
--------------------------------------------------------------------------- */
(function () {
  var all = window.DRAFT_PLAYERS || [];
  var VOL = window.VOLATILITY || {};
  var nrm = function (s) { return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, ''); };
  var SEASON = 84, PRIOR = 82;
  var G_HAIRCUT = 0.88;   // meme variance de taux que dans le bloc precedent
  var median = function (a) {
    if (!a || !a.length) return null;
    var b = a.slice().sort(function (x, y) { return x - y; }), n = b.length;
    return n % 2 ? b[(n - 1) / 2] : (b[n / 2 - 1] + b[n / 2]) / 2;
  };
  var r2 = function (x) { return Math.round(x * 100) / 100; };

  all.forEach(function (p) {
    var v = VOL[nrm(p.name)];
    var am = p.age_mult || 1;
    var projFpg = p.fpg_proj != null ? p.fpg_proj : (p.gp_proj ? p.fp_proj / p.gp_proj : 0);
    var why = [];
    var earnedFpg, floorGp;

    if (v && v.seasons && v.seasons.length) {
      // Taux gagne : on ne credite jamais un pic non repete.
      earnedFpg = v.base != null ? Math.min(v.cur, v.base) : v.cur;
      var gps = v.seasons.filter(function (s) { return s.gp >= 20; }).map(function (s) { return s.gp; });
      var m = median(gps);
      floorGp = m != null ? Math.min(Math.round(m * SEASON / PRIOR), p.gp_proj) : p.gp_proj;
      var best = Math.max.apply(null, v.seasons.map(function (s) { return s.fpg; }));
      // Drapeau le plus important : la projection depasse le meilleur taux de sa carriere.
      p.ceilBreach = projFpg > best + 0.001;
      if (p.ceilBreach) p.ceilBreachPct = Math.round(100 * (projFpg / best - 1));
      if (v.base != null && v.cur > v.base + 0.001) {
        why.push('pic non répété +' + Math.round(100 * (v.cur / v.base - 1)) + '%');
      }
    } else {
      // Aucune saison de reference : on retire au moins le bonus d'age du taux.
      earnedFpg = am ? projFpg / am : projFpg;
      floorGp = p.gp_proj;
      p.ceilBreach = false;
      why.push('aucune saison de référence');
    }

    if (am > 1.005) why.push('bonus âge +' + Math.round((am - 1) * 100) + '%');
    else if (am < 0.995) why.push('malus âge ' + Math.round((am - 1) * 100) + '%');
    if (p.gp_proj > floorGp + 1) why.push('volume accordé ' + floorGp + '\u2192' + p.gp_proj + ' MJ');

    if (p.pos === 'G') {
      // Les gardiens n'ont aucune saison dans VOLATILITY : le plancher honnete
      // est le bas de fourchette deja calcule, pas un taux x un defaut.
      p.fp_floor = p.fp_lo != null ? p.fp_lo : Math.round(earnedFpg * floorGp);
      why = [];
      if (p.gpUnknown) {
        // Volume inconnu : le plancher est une part de filet, pas un taux x des matchs.
        // On n'affiche donc aucune equation (floorGp null) pour ne rien sous-entendre.
        p.floorFpg = r2(projFpg);
        p.floorGp = null;
        why.push('volume non vérifié (plancher 52 départs)');
      } else {
        // Volume reel : le plancher applique la variance de taux (G_HAIRCUT).
        // Le taux affiche doit etre le taux APRES coupe, sinon l'equation
        // imprimee (taux x MJ) ne donne pas le plancher annonce.
        p.floorFpg = p.gp_proj ? r2(p.fp_floor / p.gp_proj) : null;
        p.floorGp = p.gp_proj;
        why.push(p.gp_proj + ' départs réels');
        why.push('variance de taux ' + Math.round(100 * (G_HAIRCUT - 1)) + '%');
      }
    } else {
      p.fp_floor = Math.round(earnedFpg * floorGp);
      p.floorFpg = r2(earnedFpg);
      p.floorGp = floorGp;
    }

    p.granted = p.fp_proj != null ? p.fp_proj - p.fp_floor : null;
    p.grantedPct = p.fp_proj ? Math.round(100 * p.granted / p.fp_proj) : 0;
    p.grantWhy = why;

    // Confiance : quelle part du classement repose sur du demontre.
    var t = p.grantedPct >= 18 ? 'fragile' : p.grantedPct >= 8 ? 'moyen' : 'solide';
    if (p.ceilBreach && t === 'solide') t = 'moyen';
    if (p.dataThin && t !== 'fragile') t = 'moyen';
    if (p.gpUnknown) t = 'fragile';
    p.trust = t;
  });

  // VORP plancher : meme calcul de remplacant, sur la base plancher.
  ['F', 'D', 'G'].forEach(function (pos) {
    var thr = { F: 73, D: 49, G: 17 }[pos];
    var at = all.filter(function (p) { return p.pos === pos; })
      .sort(function (a, b) { return b.fp_floor - a.fp_floor; });
    var rep = at[thr - 1] ? at[thr - 1].fp_floor : 0;
    at.forEach(function (p) { p.vorp_floor = Math.round(p.fp_floor - rep); });
  });
})();
